// Deterministic, serializable tactical rules. No rendering or browser dependencies.
export const SIZE={w:12,h:16};
export const SHOALS=[[3,8],[4,8],[8,6],[8,7],[2,3],[9,11]];
export const DIRECTIONS={north:[0,-1],east:[1,0],south:[0,1],west:[-1,0]};
export const clone=s=>JSON.parse(JSON.stringify(s));
export function freshBattle(){return{version:1,round:1,status:'playing',escort:{id:'escort',x:5,z:12,hp:100,facing:'north'},passenger:{id:'passenger',x:6,z:13,hp:70,facing:'north'},enemies:[{id:'raider1',x:3,z:6,hp:44,facing:'south',disabled:0},{id:'raider2',x:9,z:3,hp:44,facing:'south',disabled:0}],crew:{helm:1,guns:1,repair:1},ammo:8,timber:3,parley:true,route:'main',log:[]};}
export function water(x,z){return Number.isInteger(x)&&Number.isInteger(z)&&x>0&&x<SIZE.w-1&&z>=0&&z<SIZE.h&&!SHOALS.some(([a,b])=>a===x&&b===z);}
export function occupied(s,x,z,ignore){return[s.escort,s.passenger,...s.enemies].some(u=>u.id!==ignore&&u.hp>0&&u.x===x&&u.z===z);}
export function movePath(s,to){const a=s.escort,max=s.crew.helm?Math.min(4,1+s.crew.helm+(to.z<a.z?1:0)):1;if(!water(to.x,to.z)||occupied(s,to.x,to.z,a.id))return null;const q=[{x:a.x,z:a.z,path:[]}],seen=new Set([`${a.x},${a.z}`]);for(let i=0;i<q.length;i++){const p=q[i];if(p.x===to.x&&p.z===to.z)return p.path;if(p.path.length>=max)continue;for(const[dx,dz]of Object.values(DIRECTIONS)){const x=p.x+dx,z=p.z+dz,k=`${x},${z}`;if(water(x,z)&&!occupied(s,x,z,a.id)&&!seen.has(k)){seen.add(k);q.push({x,z,path:[...p.path,{x,z}]});}}}return null;}
export function canFire(a,b){const dx=b.x-a.x,dz=b.z-a.z;if(Math.abs(dx)+Math.abs(dz)>4)return false;return a.facing==='north'||a.facing==='south'?dz===0&&dx!==0:dx===0&&dz!==0;}
function lineClear(s,a,b){const dx=Math.sign(b.x-a.x),dz=Math.sign(b.z-a.z);let x=a.x+dx,z=a.z+dz;while(x!==b.x||z!==b.z){if(!water(x,z)||occupied(s,x,z,a.id))return false;x+=dx;z+=dz;}return true;}
function event(s,key,params={}){s.log.push({key,...params});}
export function planState(base,commands,crew=base.crew){const s=clone(base);if(s.status!=='playing')throw Error('finished');if(!crew||!['helm','guns','repair'].every(k=>Number.isInteger(crew[k])&&crew[k]>=0&&crew[k]<=3)||Object.values(crew).reduce((a,b)=>a+b,0)!==3)throw Error('crewInvalid');if(commands.length>2)throw Error('commandsFull');s.crew={...crew};s.log=[];s.guarding=false;s.anchored=false;let fired=false,repaired=false;
for(const c of commands){if(c.type==='move'){if(s.anchored)throw Error('anchored');const path=movePath(s,c);if(!path?.length)throw Error('invalidMove');let prev=s.escort;for(const p of path){s.escort.facing=p.x>prev.x?'east':p.x<prev.x?'west':p.z<prev.z?'north':'south';prev=p;}Object.assign(s.escort,path.at(-1));event(s,'moved');}
else if(c.type==='turn'){if(!DIRECTIONS[c.facing])throw Error('invalidMove');s.escort.facing=c.facing;event(s,'turned',{direction:c.facing});}
else if(c.type==='fire'){const target=s.enemies.find(e=>e.id===c.target&&e.hp>0);if(!s.crew.guns)throw Error('needGuns');if(fired)throw Error('alreadyFired');if(s.ammo<1)throw Error('noAmmo');if(!target||!canFire(s.escort,target)||!lineClear(s,s.escort,target))throw Error('badArc');if(!['hull','rigging'].includes(c.aim))throw Error('badArc');const damage=c.aim==='rigging'?8:18+s.crew.guns*4;target.hp=Math.max(0,target.hp-damage);if(c.aim==='rigging')target.disabled=2;s.ammo--;fired=true;event(s,'fired',{unit:target.id,damage});}
else if(c.type==='repair'){if(!s.crew.repair)throw Error('needRepair');if(!s.timber)throw Error('noTimber');if(repaired)throw Error('alreadyRepaired');if(s.escort.hp>=100)throw Error('fullHull');s.escort.hp=Math.min(100,s.escort.hp+14+s.crew.repair*4);s.timber--;repaired=true;event(s,'repaired');}
else if(c.type==='guard'){s.guarding=true;event(s,'guarded');}
else if(c.type==='anchor'){s.anchored=true;event(s,'anchoredLog');}
else if(c.type==='signal'){if(!['main','safe','hold'].includes(c.route))throw Error('invalidMove');s.route=c.route;event(s,'signaled',{route:c.route});}
else if(c.type==='parley'){if(!s.parley)throw Error('parleyUsed');const e=s.enemies.filter(e=>e.hp>0).sort((a,b)=>distance(a,s.passenger)-distance(b,s.passenger))[0];if(!e)throw Error('noEnemy');e.disabled=Math.max(e.disabled,1);s.parley=false;event(s,'parleyLog',{unit:e.id});}
else throw Error('unknownCommand');}return s;}
const distance=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.z-b.z);
export function forecast(base,commands,crew){const s=planState(base,commands,crew);if(s.route!=='hold'){const col=s.route==='safe'?7:6;for(let i=0;i<3;i++){const p=s.passenger;let x=p.x,z=p.z;if(x!==col)x+=Math.sign(col-x);else z--;if(z<0){s.status='won';break;}if(!water(x,z)||occupied(s,x,z,p.id))break;p.x=x;p.z=z;if(z===0){s.status='won';break;}}event(s,'passengerMoved');}
if(s.status!=='won'){for(const e of s.enemies){if(e.hp<=0)continue;if(e.disabled>0){e.disabled--;event(s,'enemyWait',{unit:e.id});continue;}const candidates=[s.passenger,s.escort].filter(u=>distance(e,u)<=4).sort((a,b)=>distance(e,a)-distance(e,b));const target=candidates[0];if(target){const damage=target.id==='escort'&&s.guarding?9:18;target.hp=Math.max(0,target.hp-damage);event(s,'enemyHit',{unit:e.id,target:target.id,damage});}else{const p=s.passenger;const steps=[[Math.sign(p.x-e.x),0],[0,Math.sign(p.z-e.z)]];for(const[dx,dz]of steps){if((dx||dz)&&water(e.x+dx,e.z+dz)&&!occupied(s,e.x+dx,e.z+dz,e.id)){e.x+=dx;e.z+=dz;break;}}event(s,'enemyMoved',{unit:e.id});}}
for(const u of[s.escort,s.passenger,...s.enemies]){if(u.hp<=0||(u.id==='escort'&&s.anchored)||(u.id==='passenger'&&s.route==='hold'))continue;if(water(u.x,u.z+1)&&!occupied(s,u.x,u.z+1,u.id))u.z++;}event(s,'drift');if(s.escort.hp<=0||s.passenger.hp<=0)s.status='lost';else if(s.enemies.every(e=>e.hp<=0))s.status='won';}
const next=clone(s);next.round++;delete next.guarding;delete next.anchored;return{planned:planState(base,commands,crew),next,events:s.log};}
export function loadBattle(storage){try{const s=JSON.parse(storage.getItem('narai-battle-v1'));if(!s||s.version!==1||!Number.isInteger(s.round)||s.round<1||!['playing','won','lost'].includes(s.status)||!Number.isInteger(s.ammo)||s.ammo<0||s.ammo>8||!Number.isInteger(s.timber)||s.timber<0||s.timber>3||typeof s.parley!=='boolean'||!['main','safe','hold'].includes(s.route)||!Array.isArray(s.log)||!Array.isArray(s.enemies)||s.enemies.length!==2)throw Error();for(const [u,id,max]of[[s.escort,'escort',100],[s.passenger,'passenger',70],...s.enemies.map((e,i)=>[e,'raider'+(i+1),44])])if(u?.id!==id||!water(u.x,u.z)||!Number.isFinite(u.hp)||u.hp<0||u.hp>max||!DIRECTIONS[u.facing]||(id.startsWith('raider')&&(!Number.isInteger(u.disabled)||u.disabled<0||u.disabled>2)))throw Error();const live=[s.escort,s.passenger,...s.enemies].filter(u=>u.hp>0);if(new Set(live.map(u=>`${u.x},${u.z}`)).size!==live.length)throw Error();const copy={...s,status:'playing'};planState(copy,[],s.crew);return s;}catch{return freshBattle();}}
export function saveBattle(storage,s){try{storage.setItem('narai-battle-v1',JSON.stringify(s));return true;}catch{return false;}}
